export const EMBERCAT=Object.freeze({speed:33.8,landingSpeed:28.6,orbitRate:.312,flightTrailLifeScale:2.5,cruiseClearance:7,airSeconds:6,castSeconds:7,transformSeconds:.8,chargeSeconds:.45,shotCooldown:1.1,shotSpeed:48,shotDamage:65,shotLife:4,range:160,maxShots:8,surfaceCheckSeconds:.25});
export class EmbercatHero {
 constructor(scene,model,{getUnits,getLanding,clearFlight,trace,onHit,groundHeight=()=>.08,cruiseHeight=45,bounds={minX:-56,maxX:56,minZ:-56,maxZ:56}}){
  Object.assign(this,{getUnits,getLanding,clearFlight,trace,onHit,groundHeight,cruiseHeight,bounds});this.root=new THREE.Group();this.root.name='Cinder Fang / fire-cat shapeshifter';scene.add(this.root);this.art=new EmbercatCharacter(this.root,model);this.character=this.art.character;this.vfx=new THREE.Group();scene.add(this.vfx);this.flames=new SolaraFireTrail(this.vfx);this.velocity=new THREE.Vector3();this.enabled=false;this.active=false;
  const geo=new THREE.IcosahedronGeometry(1,1),hot=new THREE.MeshBasicMaterial({color:'#ffd578',toneMapped:false});this.shotMesh=new THREE.InstancedMesh(geo,hot,EMBERCAT.maxShots);this.shotMesh.frustumCulled=false;this.vfx.add(this.shotMesh);this.bursts=new THREE.InstancedMesh(geo,new THREE.MeshBasicMaterial({color:'#ff661b',transparent:true,opacity:.45,depthWrite:false,toneMapped:false}),12);this.bursts.frustumCulled=false;this.vfx.add(this.bursts);this.handGlow=new THREE.Mesh(geo,hot);this.vfx.add(this.handGlow);this.dummy=new THREE.Object3D();this.reset();
 }
 reset(){this.art.reset();this.flames.reset();this.root.position.set(-20,this.cruiseHeight,24);this.root.rotation.set(0,Math.PI,0);this.velocity.set(0,0,0);this.mode='air-run';this.age=this.phaseTime=this.cooldown=this.charge=this.release=this.shots=this.hits=this.damage=this.transformations=this.landings=0;this.shotList=[];this.impacts=[];this.landing=null;this.surfaceClock=0;this.surfaceValid=null;this.flight={flameLifeScale:EMBERCAT.flightTrailLifeScale};this.shotMesh.count=this.bursts.count=0;this.handGlow.visible=false;this.root.visible=this.vfx.visible=this.enabled;}
 setEnabled(v){this.enabled=!!v;this.reset();}
 receiveEyeHit(){this.hurtUntil=this.age+.2;}
 enter(mode){this.mode=mode;this.phaseTime=0;this.surfaceClock=0;if(mode.startsWith('transform')){this.transformations++;this.burst(this.root.position.clone().add(new THREE.Vector3(0,.8,0)),2);}}
 burst(p,size=1){this.impacts.push({p:p.clone(),age:0,size});if(this.impacts.length>12)this.impacts.shift();}
 target(){const list=this.getUnits().filter(u=>u.alive&&u.kind==='robot');let best=null;for(const unit of list)for(const s of unit.shapes||[]){const p=new THREE.Vector3().copy(s.center),d=p.distanceTo(this.root.position);if(!best||d<best.d)best={unit,p,d};}return best;}
 update(dt,time){if(!this.enabled)return;const c=EMBERCAT;this.age+=dt;this.phaseTime+=dt;this.cooldown=Math.max(0,this.cooldown-dt);this.release=Math.max(0,this.release-dt*3);this.flames.update(dt);const target=this.target(),center=target?.p||new THREE.Vector3(),before=this.root.position.clone();
  if(this.mode==='air-run'){
   const a=this.age*c.orbitRate,goal=new THREE.Vector3(center.x+Math.cos(a)*26,this.cruiseHeight+Math.sin(this.age)*1.3,center.z+Math.sin(a)*26);goal.x=THREE.MathUtils.clamp(goal.x,this.bounds.minX+3,this.bounds.maxX-3);goal.z=THREE.MathUtils.clamp(goal.z,this.bounds.minZ+3,this.bounds.maxZ-3);if(this.root.position.y<this.cruiseHeight-.3){goal.x=this.root.position.x;goal.z=this.root.position.z;}this.move(goal,c.speed,dt);if(this.phaseTime>=c.airSeconds){this.landing=this.getLanding(center,this.root.position);if(this.landing)this.enter('landing');else this.phaseTime=c.airSeconds-1;}
  }else if(this.mode==='landing'){
   // Fly over the chosen point before descending vertically, never through a roof.
   const valid=this.validSurface(center,dt);if(!valid||valid.distanceTo(this.landing)>.2){this.enter('air-run');this.landing=null;}else{const horizontal=Math.hypot(this.root.position.x-this.landing.x,this.root.position.z-this.landing.z),goal=horizontal>.3?new THREE.Vector3(this.landing.x,this.cruiseHeight,this.landing.z):this.landing;this.move(goal,c.landingSpeed,dt);if(this.root.position.distanceTo(this.landing)<.12){this.root.position.copy(this.landing);this.landings++;this.enter('transform-human');}}
  }else if(this.mode==='transform-human'){if(this.phaseTime>=c.transformSeconds){this.enter('casting');this.cooldown=.35;}}
  else if(this.mode==='casting'){
   const valid=this.validSurface(center,dt);if(!valid||valid.distanceTo(this.landing)>.2){this.enter('transform-cat');this.charge=0;}else if(this.phaseTime>=c.castSeconds){this.enter('transform-cat');this.charge=0;}
   else if(target&&target.d<c.range&&this.cooldown<=0){this.charge+=dt;if(this.charge>=c.chargeSeconds){this.release=1;this.art.pose(0,time,{cat:false,target:target.p,release:1});const p=this.art.muzzle(),direction=target.p.clone().sub(p).normalize();if(this.shotList.length<c.maxShots){this.shotList.push({p:p.clone(),direction,age:0});this.shots++;}this.cooldown=c.shotCooldown;this.charge=0;}}else this.charge=0;
  }else if(this.mode==='transform-cat'){if(this.phaseTime>=c.transformSeconds)this.enter('takeoff');}
  else if(this.mode==='takeoff'){this.move(new THREE.Vector3(this.root.position.x,this.cruiseHeight,this.root.position.z),c.speed,dt);if(Math.abs(this.root.position.y-this.cruiseHeight)<.1)this.enter('air-run');}
  this.velocity.copy(this.root.position).sub(before).divideScalar(dt||1);const cat=['air-run','landing','takeoff','transform-cat'].includes(this.mode),facing=cat&&this.velocity.lengthSq()>.1?this.velocity:target?.p.clone().sub(this.root.position);let turn=0;if(facing){const yaw=Math.atan2(facing.x,facing.z);turn=Math.atan2(Math.sin(yaw-this.root.rotation.y),Math.cos(yaw-this.root.rotation.y));this.root.rotation.y+=turn*(1-Math.exp(-5*dt));}
  const transforming=this.mode.startsWith('transform');this.art.pose(dt,time,{cat,blend:transforming?Math.max(.001,Math.min(.999,this.phaseTime/c.transformSeconds)):0,velocity:this.velocity,turn,target:target?.p,charge:this.charge/c.chargeSeconds,release:this.release});
  if(cat&&this.velocity.lengthSq()>.2)this.flames.emitSegment(this.flight,before.clone().add(new THREE.Vector3(0,.5,0)),this.root.position.clone().add(new THREE.Vector3(0,.5,0)),this.velocity.clone().normalize(),dt);
  if(transforming){const a=this.age*30,p=this.root.position.clone().add(new THREE.Vector3(Math.cos(a)*.7,.8,Math.sin(a)*.7));this.flames.emitSegment({},p,p.clone().add(new THREE.Vector3(0,.5,0)),new THREE.Vector3(0,1,0),dt);}
  for(let i=this.shotList.length-1;i>=0;i--){const shot=this.shotList[i],from=shot.p.clone(),next=from.clone().addScaledVector(shot.direction,c.shotSpeed*dt),hit=this.trace(from,next);shot.p.copy(hit?.point||next);shot.age+=dt;this.flames.emitSegment(shot,from,shot.p,shot.direction,dt);if(hit||shot.age>=c.shotLife){if(hit){this.damage+=this.onHit(hit,shot.p,c.shotDamage)||0;this.hits++;this.burst(shot.p,1.8);}this.shotList.splice(i,1);}}
  this.shotMesh.count=this.shotList.length;this.shotList.forEach((s,i)=>{this.dummy.position.copy(s.p);this.dummy.scale.setScalar(.28);this.dummy.updateMatrix();this.shotMesh.setMatrixAt(i,this.dummy.matrix);});this.shotMesh.instanceMatrix.needsUpdate=true;
  this.impacts=this.impacts.filter(b=>(b.age+=dt)<.6);this.bursts.count=this.impacts.length;this.impacts.forEach((b,i)=>{this.dummy.position.copy(b.p);this.dummy.scale.setScalar(b.size*Math.sin(b.age/.6*Math.PI));this.dummy.updateMatrix();this.bursts.setMatrixAt(i,this.dummy.matrix);});this.bursts.instanceMatrix.needsUpdate=true;
  this.handGlow.visible=this.mode==='casting'&&this.charge>0;this.handGlow.position.copy(this.art.muzzle());this.handGlow.scale.setScalar(.12+.22*this.charge/c.chargeSeconds);this.flames.render(time);
 }
 validSurface(center,dt){this.surfaceClock-=dt;if(this.surfaceClock<=0){this.surfaceValid=this.getLanding(center,this.root.position,this.landing);this.surfaceClock=EMBERCAT.surfaceCheckSeconds;}return this.surfaceValid;}
 move(goal,speed,dt){const next=this.root.position.clone(),d=goal.clone().sub(next);next.add(d.clampLength(0,speed*dt));if(this.clearFlight(this.root.position,next))this.root.position.copy(next);else if(this.mode==='air-run'){const up=this.root.position.clone().add(new THREE.Vector3(0,speed*dt,0));if(this.clearFlight(this.root.position,up))this.root.position.copy(up);}else{this.enter('air-run');this.landing=null;}}
 diagnostics(){return{name:'Cinder Fang',enabled:this.enabled,controller:'cpu',mode:this.mode,speed:this.velocity.length(),flightSpeed:EMBERCAT.speed,position:this.root.position.toArray(),shots:this.shots,hits:this.hits,damage:this.damage,landings:this.landings,transformations:this.transformations,projectiles:this.shotList.length,character:this.art.diagnostics(),effects:this.flames.diagnostics()};}
}
